xl = pd.ExcelFile('/root/data.xlsx')
df = pd.read_excel(xl, sheet_name='Data', header=None)

# Extract relevant columns
data = df.iloc[9:, 2:10].copy()
data.columns = ['Turn', 'Game', 'Roll1', 'Roll2', 'Roll3', 'Roll4', 'Roll5', 'Roll6']
data = data.dropna().astype(int)

def get_rolls(row):
    """Extract the 6 dice rolls from a row."""
    return [int(row['Roll1']), int(row['Roll2']), int(row['Roll3']), 
            int(row['Roll4']), int(row['Roll5']), int(row['Roll6'])]

def score_high_and_often(rolls):
    counter = Counter(rolls)
    max_val = max(rolls)
    return max_val * counter[max_val]

def score_summation(rolls):
    return sum(rolls)

def score_highs_and_lows(rolls):
    highest = max(rolls)
    lowest = min(rolls)
    return highest * lowest * (highest - lowest)

def score_only_two_numbers(rolls):
    unique = set(rolls)
    if len(unique) == 2:
        return 30
    return 0

def score_all_the_numbers(rolls):
    if set(rolls) == {1, 2, 3, 4, 5, 6}:
        return 40
    return 0

def score_ordered_subset_of_four(rolls):
    for i in range(3):
        window = rolls[i:i+4]
        if all(window[j+1] == window[j] + 1 for j in range(3)):
            return 50
        if all(window[j+1] == window[j] - 1 for j in range(3)):
            return 50
    return 0

CATEGORIES = ['high_and_often', 'summation', 'highs_and_lows', 
              'only_two_numbers', 'all_the_numbers', 'ordered_subset_of_four']

def get_all_scores(rolls):
    return {
        'high_and_often': score_high_and_often(rolls),
        'summation': score_summation(rolls),
        'highs_and_lows': score_highs_and_lows(rolls),
        'only_two_numbers': score_only_two_numbers(rolls),
        'all_the_numbers': score_all_the_numbers(rolls),
        'ordered_subset_of_four': score_ordered_subset_of_four(rolls)
    }

def get_best_game_score(turn1_scores, turn2_scores):
    """Find the best combined score using different categories for each turn."""
    best_score = 0
    for cat1 in CATEGORIES:
        for cat2 in CATEGORIES:
            if cat1 != cat2:
                score = turn1_scores[cat1] + turn2_scores[cat2]
                if score > best_score:
                    best_score = score
    return best_score

# Group turns by game
game_turns = {}
for idx, row in data.iterrows():
    game_num = int(row['Game'])
    if game_num not in game_turns:
        game_turns[game_num] = []
    game_turns[game_num].append(get_rolls(row))

# Calculate best score for each game
game_scores = {}
for game_num in range(1, 3001):
    if game_num in game_turns:
        turns = game_turns[game_num]
        if len(turns) == 2:
            turn1_scores = get_all_scores(turns[0])
            turn2_scores = get_all_scores(turns[1])
            game_scores[game_num] = get_best_game_score(turn1_scores, turn2_scores)
        elif len(turns) == 1:
            # Game with only 1 turn - use best single score
            single_scores = get_all_scores(turns[0])
            game_scores[game_num] = max(single_scores.values())
            print(f"Game {game_num} has only 1 turn, best score: {game_scores[game_num]}")
        else:
